pub fn gc(cp: u32) -> u8 {
    let t = GC_RANGES;
    let mut lo = 0usize;
    let mut hi = t.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b, g) = t[mid];
        if cp < a {
            hi = mid;
        } else if cp > b {
            lo = mid + 1;
        } else {
            return g;
        }
    }
    0
}

pub fn gc_name(g: u8) -> &'static str {
    match g {
        1 => "Lu",
        2 => "Ll",
        3 => "Lt",
        4 => "Lm",
        5 => "Lo",
        6 => "Mn",
        7 => "Mc",
        8 => "Me",
        9 => "Nd",
        10 => "Nl",
        11 => "No",
        12 => "Pc",
        13 => "Pd",
        14 => "Ps",
        15 => "Pe",
        16 => "Pi",
        17 => "Pf",
        18 => "Po",
        19 => "Sm",
        20 => "Sc",
        21 => "Sk",
        22 => "So",
        23 => "Zs",
        24 => "Zl",
        25 => "Zp",
        26 => "Cc",
        27 => "Cf",
        28 => "Cs",
        29 => "Co",
        0 => "Cn",
        _ => "Cn",
    }
}

pub fn gc_eq(cp: u32, name: &str) -> bool {
    let g = gc(cp);
    if name.len() == 1 {
        return gc_name(g).as_bytes().first().copied() == name.as_bytes().first().copied();
    }
    gc_name(g) == name
}

